```python
class User(Base):
    __tablename__ = "user"
    id = mapped_column(Integer, primary_key=True)

    @property
    def addresses(self):
        # query using any kind of filter() criteria
        return (
            object_session(self)
            .query(Address)
            .filter(Address.user_id == self.id)
            .filter(...)
            .all()
        )
```

